import{_ as a,C as n,c as i,o as r,a3 as o,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Cash in and out","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/sessions/cash-in-and-out.md","filePath":"master/sales/point-of-sale/sessions/cash-in-and-out.md","lastUpdated":1791902625000}'),l={name:"master/sales/point-of-sale/sessions/cash-in-and-out.md"};function h(c,e,d,m,u,p){const t=n("ImagePopup");return r(),i("div",null,[e[0]||(e[0]=o('<h1 id="cash-in-and-out" tabindex="-1">Cash in and out <a class="header-anchor" href="#cash-in-and-out" aria-label="Permalink to &quot;Cash in and out&quot;">​</a></h1><p>Sometimes cash enters or leaves the drawer without a sale. You may pay a courier, buy supplies or add change from the safe. Cash in and out records these movements, so the drawer still balances at closing.</p><blockquote><p><strong>In simple words:</strong> Write down every coin that goes into or out of the drawer outside a sale.</p></blockquote><p>A movement is tied to the live session. It changes the expected balance you see when you close.</p><h2 id="record-a-movement-in-the-back-office" tabindex="-1">Record a movement in the back office <a class="header-anchor" href="#record-a-movement-in-the-back-office" aria-label="Permalink to &quot;Record a movement in the back office&quot;">​</a></h2><ol><li>Go to <code>Point of Sale → Orders → Sessions</code>.</li><li>Find the session that is <strong>In Progress</strong>.</li><li>Click <strong>Cash In/Out</strong> on its row. The <strong>Cash In/Out</strong> window opens.</li></ol>',6)),s(t,{src:"/images1/pos/sessions_row_actions.png",alt:"Sessions list with the In Progress session and the View, Cash In/Out and Close Session actions"}),e[1]||(e[1]=o('<ol start="4"><li>Fill in the form.</li></ol><ul><li><strong><em>Type:</em></strong> Choose <strong>Cash In</strong> to add money or <strong>Cash Out</strong> to take money. Required.</li><li><strong><em>Amount:</em></strong> The amount moved. Required.</li><li><strong><em>Reason:</em></strong> A short explanation. Staff read it when they check the session later.</li></ul><ol start="5"><li>Click <strong>Submit</strong>. A notice says <strong>Cash movement recorded</strong>.</li></ol>',3)),s(t,{src:"/images1/pos/cash_out_window.png",alt:"Cash In/Out window with Type Cash Out, Amount 500 and Reason Paid courier for same day delivery"}),e[2]||(e[2]=o('<p><strong>Example:</strong> TechNest pays a courier 500 for a same day delivery. Choose <strong>Cash Out</strong>, enter 500 and write &quot;Paid courier for same day delivery&quot;.</p><h2 id="record-a-movement-at-the-terminal" tabindex="-1">Record a movement at the terminal <a class="header-anchor" href="#record-a-movement-at-the-terminal" aria-label="Permalink to &quot;Record a movement at the terminal&quot;">​</a></h2><p>The till has the same feature, so the cashier does not have to leave the screen.</p><ol><li>Click your initials at the top right of the terminal.</li><li>Click <strong>Cash In / Out</strong>.</li><li>Choose <strong>Cash in</strong> or <strong>Cash out</strong>, then enter the <strong>Amount</strong> and the <strong>Reason</strong>.</li><li>Click <strong>Record movement</strong>.</li></ol>',4)),s(t,{src:"/images1/pos/terminal_cash_in_out.png",alt:"Terminal Cash in / out window with Cash out selected, amount 500, a reason and the Record movement button"}),e[3]||(e[3]=o('<p>The terminal confirms with the message <strong>Cash movement recorded</strong>. For example, &quot;500 taken out of the cash drawer.&quot;</p><h2 id="how-it-affects-closing" tabindex="-1">How it affects closing <a class="header-anchor" href="#how-it-affects-closing" aria-label="Permalink to &quot;How it affects closing&quot;">​</a></h2><p>The drawer should hold this amount at closing:</p><p>opening cash + cash payments + cash in - cash out</p><p>For TechNest: 1,750 opening + 6,597 cash sales (7,000 paid less 403 change) - 500 cash out = 7,847. The refund of the Nova X5 is paid back in cash, so its net effect with the original sale is zero. That is why the counted amount of 7,847 matches. See <a href="./close-session.html">Close a session</a>.</p><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><p>You can record movements only while the session is <strong>In Progress</strong>. After the session closes, the movements are fixed.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Always write a clear reason. A note like &quot;courier&quot; is easier to check than an empty field.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not take cash out of the drawer without recording it. The difference shows up at closing.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Register sessions</a></li><li><a href="./close-session.html">Close a session</a></li><li><a href="./../selling/take-an-order.html">Take an order</a></li></ul>',11))])}const _=a(l,[["render",h]]);export{f as __pageData,_ as default};
